# 27 consulting firms: (slug, name, url, verified fact, observation 1, observation 2, slide notes)
import json, os
_P = os.path.join(os.path.dirname(__file__), 'notes.json')
_N = json.load(open(_P)) if os.path.exists(_P) else {}
_B = [
("mckinsey-and-company","McKinsey & Company","https://www.mckinsey.com/","James O. McKinsey founded the firm in Chicago in 1926.","A refined serif sets the name over two lines, with \"& Company\" indented under McKinsey.","Dark navy and old-style letters make the brand feel like a private bank or a law firm."),
("boston-consulting-group","Boston Consulting Group","https://www.bcg.com/","Bruce Henderson founded BCG in Boston in 1963.","Three white letters sit in a solid green square, so the firm is known by its initials.","Green is rare among strategy firms and makes the mark easy to spot on a crowded page."),
("bain-and-company","Bain & Company","https://www.bain.com/","Bill Bain and other former BCG consultants founded Bain & Company in Boston in 1973.","Widely spaced red capitals spell out the full name with an ampersand.","A small circle with a pointer at the end works as a compact symbol for social icons."),
("oliver-wyman","Oliver Wyman","https://www.oliverwyman.com/","Oliver Wyman was founded in New York in 1984 and is now part of Marsh McLennan.","Heavy, wide capitals make the two names look solid and modern.","The line \"A Marsh Business\" under the name shows the parent company inside the logo."),
("kearney","Kearney","https://www.kearney.com/","Kearney traces its history to 1926 and shortened its name from A.T. Kearney in 2020.","Thin, very widely spaced capitals make the name feel calm and precise.","For its centenary the logo adds a 100 in a pink-to-purple gradient, the only colour in the mark."),
("roland-berger","Roland Berger","https://www.rolandberger.com/","Roland Berger founded the firm in Munich in 1967, and it is one of Europe's largest strategy consultancies.","The founder's name is stacked over two lines in a rounded geometric sans serif.","With no symbol and no colour, the logo relies entirely on the shape of the letters."),
("lek-consulting","L.E.K. Consulting","https://www.lek.com/","L.E.K. Consulting was founded in London in 1983 by Jim Lawrence, Iain Evans and Richard Koch.","Three heavy capitals are spaced far apart, one for each founder's surname.","A green cut inside the K is the only colour, a small detail that makes the mark recognisable."),
("strategy-and","Strategy&","https://www.strategyand.pwc.com/","Strategy& is the strategy consulting arm of PwC, formed from Booz & Company in 2014.","A heavy serif sets the name in lowercase, which feels confident but approachable.","The ampersand ending the name hints at partnership and makes the name easy to remember."),
("simon-kucher","Simon-Kucher","https://www.simon-kucher.com/","Simon-Kucher was founded in Bonn, Germany, in 1985 and is known for pricing strategy.","The founders' surnames are stacked in bold capitals with a cluster of red diamonds.","The strapline \"Unlocking better growth\" sits under the name in the same red."),
("deloitte","Deloitte","https://www.deloitte.com/","William Welch Deloitte opened his first office in London in 1845.","A heavy, rounded sans serif sets the name in black.","The bright green dot after the name is the most recognisable full stop in professional services."),
("pwc","PwC","https://www.pwc.com/","PwC was formed in 1998 when Price Waterhouse merged with Coopers & Lybrand.","A heavy lowercase serif makes the three letters feel solid and friendly.","Two orange blocks above the letters are a simplified version of the firm's earlier colourful mark."),
("ey","EY","https://www.ey.com/","Ernst & Young shortened its name to EY in 2013.","Two heavy capitals sit under a yellow beam that slopes upward.","The beam is a visual hint at progress and makes the short name feel energetic."),
("kpmg","KPMG","https://kpmg.com/","KPMG was formed in 1987 when Peat Marwick International merged with Klynveld Main Goerdeler.","Italic blue capitals lean forward under a row of four outlined boxes.","Each box sits over one letter, which turns an acronym into a structured mark."),
("accenture","Accenture","https://www.accenture.com/","Andersen Consulting renamed itself Accenture in 2001.","A simple lowercase wordmark keeps the long name easy to read.","A purple greater-than sign above the t points forward and works as a standalone symbol."),
("capgemini","Capgemini","https://www.capgemini.com/","Serge Kampf founded Capgemini in Grenoble, France, in 1967.","The name is set in flowing blue script, unusual for a large consulting firm.","A spade symbol at the end of the name gives the brand a card-game twist."),
("booz-allen-hamilton","Booz Allen Hamilton","https://www.boozallen.com/","Edwin G. Booz founded the firm in Chicago in 1914.","Heavy, tight black letters shorten the name to Booz Allen.","A small full stop after the name gives it a decisive finish."),
("alvarez-and-marsal","Alvarez & Marsal","https://www.alvarezandmarsal.com/","Tony Alvarez and Bryan Marsal founded the firm in New York in 1983.","A tall blue A shaped like a tower is the main symbol.","The letters A, & and M are stacked vertically beside the tower."),
("fti-consulting","FTI Consulting","https://www.fticonsulting.com/","FTI Consulting was founded in Annapolis, Maryland, in 1982 as Forensic Technologies International.","A navy symbol of columns looks like a classical building.","The initials are spaced far apart over a thin line of small capitals."),
("arthur-d-little","Arthur D. Little","https://www.adlittle.com/","Arthur Dehon Little founded the firm in Cambridge, Massachusetts, in 1886, making it one of the oldest consultancies.","Navy capitals are spaced widely across the full name.","The D in the middle is a blue shape that doubles as a symbol."),
("zs","ZS","https://www.zs.com/","Andris Zoltners and Prabhakant Sinha founded ZS in Evanston, Illinois, in 1983.","A light grey ZS sits next to a mark made of grey and orange stripes.","The striped mark suggests data and layers, which fits a firm focused on analytics."),
("huron","Huron","https://www.huronconsultinggroup.com/","Huron was founded in Chicago in 2002 and focuses on healthcare, education and commercial clients.","Very wide, heavy capitals make the short name feel strong and technical.","The logo uses only black, so the shape of the letters does all the work."),
("guidehouse","Guidehouse","https://guidehouse.com/","Guidehouse was formed in 2018 from PwC's US public sector business.","A black and green arrow mark points upward like a guide.","A bold sans serif keeps the name clear next to the sharp symbol."),
("west-monroe","West Monroe","https://www.westmonroe.com/","West Monroe was founded in Chicago in 2002.","A ring of navy squares and dots forms an open circle.","The name is set in lowercase, which makes the firm feel friendly and modern."),
("slalom","Slalom","https://www.slalom.com/","Slalom was founded in Seattle in 2001.","Bright blue lowercase letters are the whole logo.","The rounded, heavy letters feel more like a tech brand than a consulting firm."),
("mercer","Mercer","https://www.mercer.com/","William Manson Mercer founded the firm in Vancouver in 1945, and it is now part of Marsh McLennan.","A navy symbol looks like a folded ribbon or two linked shapes.","A clean sans serif name in the same navy keeps the logo simple."),
("capco","Capco","https://www.capco.com/","Capco was founded in 1998 and focuses on consulting for financial services.","Tall, condensed black capitals make the short name look bold.","With no symbol and no colour, the logo looks like a headline."),
("korn-ferry","Korn Ferry","https://www.kornferry.com/","Lester Korn and Richard Ferry founded the firm in Los Angeles in 1969.","A green square holds a KF monogram, next to the founders' names in stacked capitals.","The monogram works on its own as a small icon."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 27
